import{_ as t,a,c as o,ac as s}from"./chunks/framework.BSuaGltH.js";const m=JSON.parse('{"title":"第一册：英语初阶 · 综合复习与自测 · 第123–129课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","frontmatter":{"title":"第一册：英语初阶 · 综合复习与自测 · 第123–129课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","splitFrom":"life/english/new-concept/book-1/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第一册：英语初阶 · 综合复习与自测","summary":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · 综合复习与自测 · 第116–122课","link":"/life/english/new-concept/book-1/review-part-17"},"next":{"text":"第一册：英语初阶 · 综合复习与自测 · 第130–136课","link":"/life/english/new-concept/book-1/review-part-19"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · 综合复习与自测 · 第116–122课","link":"/life/english/new-concept/book-1/review-part-17"},"next":{"text":"第一册：英语初阶 · 综合复习与自测 · 第130–136课","link":"/life/english/new-concept/book-1/review-part-19"}},"headers":[],"relativePath":"life/english/new-concept/book-1/review-part-18.md","filePath":"life/english/new-concept/book-1/review-part-18.md"}'),n={name:"life/english/new-concept/book-1/review-part-18.md"};function r(i,e,h,l,p,d){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="第一册-英语初阶-·-综合复习与自测-·-第123–129课" tabindex="-1">第一册：英语初阶 · 综合复习与自测 · 第123–129课 <a class="header-anchor" href="#第一册-英语初阶-·-综合复习与自测-·-第123–129课" aria-label="Permalink to &quot;第一册：英语初阶 · 综合复习与自测 · 第123–129课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-1/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-1/overview">本册介绍</a> · <a href="/life/english/new-concept/book-1/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-1/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-1/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-1/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-1/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-1/review">综合复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-123-·-关系代词作宾语" tabindex="-1">Lesson 123 · 关系代词作宾语 <a class="header-anchor" href="#lesson-123-·-关系代词作宾语" aria-label="Permalink to &quot;Lesson 123 · 关系代词作宾语 {#lesson-123-·-关系代词作宾语}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The guide we met in Perth spoke three languages.</p><h3 id="练习-1-122" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-122" aria-label="Permalink to &quot;练习 1 {#练习-1-122}&quot;">​</a></h3><p>在 the guide that we met 中，that 能省略吗？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 能；that 在限制性定语从句中作 met 的宾语。</p><p><strong>解析：</strong> 按本课规则判断：在限制性定语从句中，关系代词若作宾语，常可省略，如 the place we visited。指人正式文体可用 whom，口语中 who 或省略更常见。省略的前提是从句已有主语而缺宾语；关系代词作主语时不能随便省略。visit 是及物动词，visit the city 不需额外加 to，但 go to the city 需要 to。</p></details><p><strong>表达迁移：</strong> 围绕“讲述旅行中见到的人与事物”写两至三句，再读给同伴听。至少使用一次关系代词作宾语，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The guide we met in Perth spoke three languages. This is the photograph that I took at the harbour.</p><p>The guide 是先行词；we met 中 we 为主语，被省略的关系代词是 met 的宾语；spoke 是主句谓语。 That 在从句 I took 中作宾语，可在这一限制性从句中省略；at the harbour 表拍照地点。</p></details><p><a href="/life/english/new-concept/book-1/unit-06/lesson-123">回看本课</a></p><h2 id="lesson-124-·-关系代词作宾语" tabindex="-1">Lesson 124 · 关系代词作宾语 <a class="header-anchor" href="#lesson-124-·-关系代词作宾语" aria-label="Permalink to &quot;Lesson 124 · 关系代词作宾语 {#lesson-124-·-关系代词作宾语}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> This is the photograph that I took at the harbour.</p><h3 id="练习-1-123" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-123" aria-label="Permalink to &quot;练习 1 {#练习-1-123}&quot;">​</a></h3><p>改正：the photograph that I took it.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> the photograph that I took</p><p><strong>解析：</strong> 按本课规则判断：在限制性定语从句中，关系代词若作宾语，常可省略，如 the place we visited。指人正式文体可用 whom，口语中 who 或省略更常见。省略的前提是从句已有主语而缺宾语；关系代词作主语时不能随便省略。visit 是及物动词，visit the city 不需额外加 to，但 go to the city 需要 to。</p></details><p><strong>表达迁移：</strong> 围绕“讲述旅行中见到的人与事物”写两至三句，再读给同伴听。至少使用一次关系代词作宾语，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>This is the photograph that I took at the harbour. The guide we met in Perth spoke three languages.</p><p>That 在从句 I took 中作宾语，可在这一限制性从句中省略；at the harbour 表拍照地点。 The guide 是先行词；we met 中 we 为主语，被省略的关系代词是 met 的宾语；spoke 是主句谓语。</p></details><p><a href="/life/english/new-concept/book-1/unit-06/lesson-124">回看本课</a></p><h2 id="lesson-125-·-have-to-的时态与否定" tabindex="-1">Lesson 125 · have to 的时态与否定 <a class="header-anchor" href="#lesson-125-·-have-to-的时态与否定" aria-label="Permalink to &quot;Lesson 125 · have to 的时态与否定 {#lesson-125-·-have-to-的时态与否定}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> I had to water the plants before work.</p><h3 id="练习-1-124" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-124" aria-label="Permalink to &quot;练习 1 {#练习-1-124}&quot;">​</a></h3><p>填过去形式：Yesterday I ___ to water the plants.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> had</p><p><strong>解析：</strong> 按本课规则判断：have to 常表示客观要求，第三人称为 has to，过去为 had to，未来可用 will have to。疑问和否定借助 do/does/did：Does she have to ...?、She doesn&#39;t have to ...。must 没有普通过去式，过去的义务常用 had to。don&#39;t need to 与 don&#39;t have to 都能表示不必，不能误读为禁止。</p></details><p><strong>表达迁移：</strong> 围绕“说明不得不做与不需要做”写两至三句，再读给同伴听。至少使用一次have to 的时态与否定，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>I had to water the plants before work. She does not have to work this Sunday.</p><p>Had to 是过去的客观必要，后接原形 water；plants 是宾语，before work 表发生时间。 Does not have to 表第三人称单数的“不必”；have 恢复原形，this Sunday 指本次星期日。</p></details><p><a href="/life/english/new-concept/book-1/unit-06/lesson-125">回看本课</a></p><h2 id="lesson-126-·-have-to-的时态与否定" tabindex="-1">Lesson 126 · have to 的时态与否定 <a class="header-anchor" href="#lesson-126-·-have-to-的时态与否定" aria-label="Permalink to &quot;Lesson 126 · have to 的时态与否定 {#lesson-126-·-have-to-的时态与否定}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> She does not have to work this Sunday.</p><h3 id="练习-1-125" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-125" aria-label="Permalink to &quot;练习 1 {#练习-1-125}&quot;">​</a></h3><p>填 have/has：She does not ___ to work.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> have</p><p><strong>解析：</strong> 按本课规则判断：have to 常表示客观要求，第三人称为 has to，过去为 had to，未来可用 will have to。疑问和否定借助 do/does/did：Does she have to ...?、She doesn&#39;t have to ...。must 没有普通过去式，过去的义务常用 had to。don&#39;t need to 与 don&#39;t have to 都能表示不必，不能误读为禁止。</p></details><p><strong>表达迁移：</strong> 围绕“说明不得不做与不需要做”写两至三句，再读给同伴听。至少使用一次have to 的时态与否定，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>She does not have to work this Sunday. I had to water the plants before work.</p><p>Does not have to 表第三人称单数的“不必”；have 恢复原形，this Sunday 指本次星期日。 Had to 是过去的客观必要，后接原形 water；plants 是宾语，before work 表发生时间。</p></details><p><a href="/life/english/new-concept/book-1/unit-06/lesson-126">回看本课</a></p><h2 id="lesson-127-·-must-cannot-表现在推断" tabindex="-1">Lesson 127 · must/cannot 表现在推断 <a class="header-anchor" href="#lesson-127-·-must-cannot-表现在推断" aria-label="Permalink to &quot;Lesson 127 · must/cannot 表现在推断 {#lesson-127-·-must-cannot-表现在推断}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The office lights are on; someone must be inside.</p><h3 id="练习-1-126" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-126" aria-label="Permalink to &quot;练习 1 {#练习-1-126}&quot;">​</a></h3><p>表达强推断：Someone ___ be inside.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> must</p><p><strong>解析：</strong> 按本课规则判断：must be 在推断中表示根据证据很有把握，不能译为命令意义的“必须是”。can&#39;t be 表根据证据认为不可能；may/might be 表不确定的可能。推断应说明证据，不能把 must 当成证明。情态动词后用原形 be，即便主语是 he/she 也不改为 is。</p></details><p><strong>表达迁移：</strong> 围绕“根据线索推测身份或当前状态”写两至三句，再读给同伴听。至少使用一次must/cannot 表现在推断，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The office lights are on; someone must be inside. That cannot be our bus; it has a different number.</p><p>前半句灯亮着是观察线索；后半句 must be 是强推断，someone 是主语，inside 为地点表语。 Cannot be 表不可能是；分号后 different number 提供推断依据，its number 与 expected bus number 不同。</p></details><p><a href="/life/english/new-concept/book-1/unit-06/lesson-127">回看本课</a></p><h2 id="lesson-128-·-must-cannot-表现在推断" tabindex="-1">Lesson 128 · must/cannot 表现在推断 <a class="header-anchor" href="#lesson-128-·-must-cannot-表现在推断" aria-label="Permalink to &quot;Lesson 128 · must/cannot 表现在推断 {#lesson-128-·-must-cannot-表现在推断}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> That cannot be our bus; it has a different number.</p><h3 id="练习-1-127" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-127" aria-label="Permalink to &quot;练习 1 {#练习-1-127}&quot;">​</a></h3><p>表达不可能：That ___ be our bus.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> cannot / can&#39;t</p><p><strong>解析：</strong> 按本课规则判断：must be 在推断中表示根据证据很有把握，不能译为命令意义的“必须是”。can&#39;t be 表根据证据认为不可能；may/might be 表不确定的可能。推断应说明证据，不能把 must 当成证明。情态动词后用原形 be，即便主语是 he/she 也不改为 is。</p></details><p><strong>表达迁移：</strong> 围绕“根据线索推测身份或当前状态”写两至三句，再读给同伴听。至少使用一次must/cannot 表现在推断，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>That cannot be our bus; it has a different number. The office lights are on; someone must be inside.</p><p>Cannot be 表不可能是；分号后 different number 提供推断依据，its number 与 expected bus number 不同。 前半句灯亮着是观察线索；后半句 must be 是强推断，someone 是主语，inside 为地点表语。</p></details><p><a href="/life/english/new-concept/book-1/unit-06/lesson-128">回看本课</a></p><h2 id="lesson-129-·-情态动词-have-done" tabindex="-1">Lesson 129 · 情态动词 + have done <a class="header-anchor" href="#lesson-129-·-情态动词-have-done" aria-label="Permalink to &quot;Lesson 129 · 情态动词 + have done {#lesson-129-·-情态动词-have-done}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The road is wet; it must have rained overnight.</p><h3 id="练习-1-128" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-128" aria-label="Permalink to &quot;练习 1 {#练习-1-128}&quot;">​</a></h3><p>填分词：It must have ___ (rain).</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> rained</p><p><strong>解析：</strong> 按本课规则判断：must have + 过去分词表示对过去的强推断，can&#39;t have + 过去分词表示认为过去不可能发生。它们不是现在完成时的普通肯否定，而是情态推断结构。过去状态用 have been，过去动作使用相应分词。速度等信息应作为证据，不要把猜测说成亲眼观察；本页只练语言，不判断实际交通责任。</p></details><p><strong>表达迁移：</strong> 围绕“根据现在的证据推测过去”写两至三句，再读给同伴听。至少使用一次情态动词 + have done，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The road is wet; it must have rained overnight. He cannot have read the sign; it was covered.</p><p>The road is wet 是现在证据；must have rained 对过去下雨作推断，overnight 指夜里。 Cannot have read 对过去是否读到标志作否定推断；it was covered 给出证据，但推断本身不是亲眼观察。</p></details><p><a href="/life/english/new-concept/book-1/unit-06/lesson-129">回看本课</a></p>',60)])])}const u=t(n,[["render",r]]);export{m as __pageData,u as default};
